INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin','秦','["秦","嬴秦","秦国"]',NULL,'{"periods":[{"rank":"伯","start":{"year":-770,"month":1,"confidence":"year"},"end":{"year":-326,"month":12,"confidence":"year"}},{"rank":"王","start":{"year":-325,"month":1,"confidence":"year"},"end":{"year":-222,"month":12,"confidence":"year"}},{"rank":"帝","start":{"year":-221,"month":1,"confidence":"year"},"end":{"year":-207,"month":12,"confidence":"month"}}]}','cn','east_asia',-778,1,NULL,'year',-207,12,NULL,'month',-9324,-2461,'ochre',NULL,NULL,'前778年秦襄公即位；前770年护周平王东迁列为诸侯；前221年嬴政称帝统一；前207年子婴降，秦亡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bai-qi','白起','qin','[]',NULL,NULL,-332,1,NULL,'year',-257,1,NULL,'year','["军事家"]','战国秦国名将，长期为秦昭襄王攻城略地，伊阙、长平等战役重创韩、魏、赵军。长平之战后处置赵军降卒的记载影响深远；后因与秦相范雎失和，被赐死于杜邮。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/白起"}]',NULL,NULL,NULL,'[]');
