INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r23','师隰','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','止殉、迁栎阳，收复部分失地。商鞅入秦前秦国已有革新，国势渐起，为孝公奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦献公"}]','献公',NULL,'秦献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r25','驷','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杀商鞅而沿用其法，灭巴蜀，臣平周王。秦国首称王号，国势强盛，为统一奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦惠文王"}]','惠文王',NULL,'秦惠文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r26','荡','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武王，举鼎绝膑而亡。在位仅四年，秦国继续扩张，国势强盛，无力维持长期霸业，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦武王"}]','武王',NULL,'秦武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r27','稷','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位五十六年，诱杀楚怀王，长平灭赵。为秦国一统奠定决定性基础，国势巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦昭襄王"}]','昭襄王',NULL,'秦昭襄王','[]');
