INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r8','任好','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位三十九年，霸西戎，为春秋五霸之一。晚年兵败晋国，国力由盛转衰，霸业渐失，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦穆公"}]','穆公',NULL,'秦穆公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qin-r9','罃','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','康公，穆公之子。在位十一年，秦国维持现状，国势平稳，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦康公"}]','康公',NULL,'秦康公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shang-yang','商鞅','qin','[]',NULL,NULL,-390,1,NULL,'year',-338,1,NULL,'year','["政治家"]','卫国人，秦孝公时主持变法，奠定秦统一基础；入秦后受封商於，推行军功爵、县制等改革。孝公去世后失去支持，前338年遭车裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/商鞅"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-jian-qin','王翦','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','战国末秦国名将，秦王政统一战争的主要统帅。率军灭赵、燕、楚，灭楚时以持重用兵著称；秦统一后退居故里。其子王贲亦为秦将。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王翦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-qi','开','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','护送周平王东迁有功，受封诸侯。伐戎建初功，秦国始为一方诸侯，开启霸业之路，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦襄公"}]','襄公',NULL,'秦襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-quliang','渠梁','qin','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','颁布求贤令，用商鞅变法，迁都咸阳。奠定秦国富强基础，为统一六国铺路，开启霸业新篇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦孝公"}]','孝公',NULL,'秦孝公','[]');
